'use strict';
/* The owner board presents quoted choices. Only engine actions change a campaign. */
const ownershipUI={city:null};
const ownerText=v=>esc(v==null?'':v);
const ownerArray=v=>Array.isArray(v)?v:[];
const ownerMoney=n=>kr(Number.isFinite(n)?n:0);
const ownerSign=n=>(n>0?'+':'')+ownerText(n);
function ownerInfo(){return typeof G.ownershipInfo==='function'?G.ownershipInfo(s):{projects:[],pending:[],invested:0,income:0,upkeep:0,control:0,automated:false,policy:'manual'};}
function ownerCityName(city){return G.CITIES[city]?.name||'Byen';}
function ownerPathName(path){const definition=ownerArray(G.OWNERSHIP_PATHS).find(p=>p.id===path);return definition?.name||(path==='control'?'Egen kontroll':path==='partners'?'Lokale medeiere':'Ingen avtale');}
function ownerEffects(effects={}){const rows=[];if(Number.isFinite(effects.control))rows.push('Din eierandel '+ownerText(effects.control)+' %');if(Number.isFinite(effects.pressure)&&effects.pressure)rows.push(ownerSign(effects.pressure)+' rivalpress');if(Number.isFinite(effects.loyalty)&&effects.loyalty)rows.push(ownerSign(effects.loyalty)+' lojalitet');if(Number.isFinite(effects.enemy)&&effects.enemy)rows.push((effects.enemy>0?'+':'')+ownerText((effects.enemy*100).toLocaleString('nb-NO',{maximumFractionDigits:1}))+' % rivalstyrke');if(Number.isFinite(effects.influence)&&effects.influence)rows.push(ownerSign(effects.influence)+' innflytelse');if(Number.isFinite(effects.heat)&&effects.heat)rows.push(ownerSign(effects.heat)+' søkelys');if(Number.isFinite(effects.tension)&&effects.tension)rows.push(ownerSign(effects.tension)+' spenning');if(Number.isFinite(effects.incomeShare)&&effects.incomeShare)rows.push(ownerSign(Math.round(effects.incomeShare*100))+' % av brutto til deg');if(Number.isFinite(effects.regionalSlotsGain)&&effects.regionalSlotsGain)rows.push(ownerSign(effects.regionalSlotsGain)+' regionalt kontrollspenn');return rows.length?`<ul class="owner-effects">${rows.map(t=>`<li>${t}</li>`).join('')}</ul>`:'';}
function ownerPick(info){const projects=ownerArray(info.projects);if(projects.some(p=>p.city===ownershipUI.city))return projects.find(p=>p.city===ownershipUI.city);const pending=ownerArray(info.pending)[0];return projects.find(p=>p.city===pending?.city)||projects.find(p=>p.project)||projects.find(p=>ownerArray(p.quotes).some(q=>q.valid))||projects.find(p=>p.level>0)||projects[0];}
function ownerPhase(card){if(card.project)return 'Overtakelse i gang';if(card.level>0)return card.level>=card.maxLevel?'Avtalen er utbygd':'Nivå '+card.level+' av '+card.maxLevel;return 'Et nytt bord';}
function ownerCityTabs(info,selected){return `<div class="owner-city-tabs" role="group" aria-label="Velg en by ved eierbordet">${ownerArray(info.projects).map(p=>{const pending=ownerArray(info.pending).some(d=>d.city===p.city);return `<button data-owner-city="${p.city}" aria-pressed="${p.city===selected.city}" class="${p.city===selected.city?'selected':''}"><span>${ownerText(ownerCityName(p.city))}</span><small>${pending?'Svar venter ●':ownerText(ownerPhase(p))}</small></button>`;}).join('')}</div>`;}
function ownerProgress(card){const p=card.project;if(!p)return '';return `<section class="owner-progress"><div class="between"><span class="section-kicker">LEDERNE FØLGER OPP / NIVÅ ${ownerText(p.level)}</span><b>${ownerText(p.progress)} / ${ownerText(p.need)} uker</b></div>${meter(p.need?p.progress/p.need*100:0)}<p>${ownerText(card.deliveryRequirement||ownerArray(card.quotes)[0]?.deliveryRequirement||'Lederne bygger avtalen gjennom faktiske driftsuker med leveranser og et lojalt lag.')}</p>${p.pauseReason?`<p class="owner-pause">${ownerText(p.pauseReason)}</p>`:'<small>Neste fremdrift vurderes ved et faktisk ukeoppgjør. Du trenger ikke sende varer manuelt.</small>'}</section>`;}
function ownerQuoteCard(q,card){const atMax=card.level>=card.maxLevel;return `<article class="owner-path ${q.path==='control'?'owner-path-control':''}"><span class="section-kicker">${card.level?'BYGG VIDERE PÅ AVTALEN':'VELG HVEM SOM FÅR EN STOL'}</span><h3>${ownerText(q.label||ownerPathName(q.path))}</h3><p>${ownerText(q.text)}</p>${ownerEffects(q.effects)}<div class="owner-quote-money"><span>Kapital til neste trinn<strong>${ownerMoney(q.cost)}</strong></span><span>Anslått ekstra netto / uke<strong>+${ownerMoney(q.weeklyNet)}</strong></span></div><details class="owner-quote-detail"><summary>Se regnestykket og forutsetningene</summary><dl><div><dt>Ekstra brutto / uke</dt><dd>${ownerMoney(q.weeklyGross)}</dd></div><div><dt>Ekstra drift / uke</dt><dd>−${ownerMoney(q.weeklyUpkeep)}</dd></div><div><dt>Forsiktig nettoanslag / uke</dt><dd>${ownerMoney(q.conservativeWeeklyNet)}</dd></div><div><dt>Anslått tilbakebetaling</dt><dd>${Number.isFinite(q.payback)?Math.ceil(q.payback)+' uker':'Ikke lønnsomt'}</dd></div><div><dt>Tid igjen til 2036</dt><dd>${Math.max(0,Math.floor(q.remaining||0))} uker</dd></div></dl><p>${ownerText(q.deliveryRequirement||'Overtakelsen krever åtte driftsuker med leveranser og minst 55 lojalitet.')} Beløpene er før valgt driftsstrategi. Tilbakebetalingen inkluderer oppbyggingen. Drift, rivaler, sesong og tid uten fremdrift kan endre resultatet.</p></details>${q.reason?`<p class="owner-quote-reason">${ownerText(q.reason)}</p>`:''}<button class="button ${q.path==='control'?'ghost':'brass'}" data-owner-invest="${card.city}" data-owner-path="${ownerText(q.path)}" data-owner-level="${q.level}" ${!q.valid||s.ended?'disabled':''}>${atMax?'Avtalen er utbygd':card.level?'Se utvidelsen':'Se avtalen'} →</button></article>`;}
function ownerDecision(decision){return `<section class="owner-decision" aria-labelledby="owner-decision-title"><div class="owner-decision-byline"><span class="owner-envelope" aria-hidden="true">↳</span><span class="section-kicker">${ownerText(decision.speaker)} / ${ownerText(ownerCityName(decision.city))}</span></div><h2 id="owner-decision-title">${ownerText(decision.title)}</h2><p class="owner-decision-text">${ownerText(decision.text)}</p>${decision.waitingText?`<p class="owner-waiting-cost"><b>Mens tilbudet ligger åpent</b>${ownerText(decision.waitingText)}</p>`:''}<div class="owner-response-grid">${ownerArray(decision.choices).map(q=>`<article><h3>${ownerText(q.label)}</h3><p>${ownerText(q.text)}</p>${ownerEffects(q.effects)}<span class="owner-response-cost">${q.cost?'Kostnad '+ownerMoney(q.cost):'Ingen engangsutbetaling'}</span>${q.reason?`<p class="owner-quote-reason">${ownerText(q.reason)}</p>`:''}<button class="button ghost" data-owner-respond="${decision.city}" data-owner-choice="${ownerText(q.id)}" data-owner-revision="${decision.revision}" ${!q.valid||s.ended?'disabled':''}>${q.cost?'Se svaret':'Velg dette svaret'} →</button></article>`).join('')}</div><p class="owner-decision-note">Driften fortsetter mens du vurderer. Et åpent mottilbud må avgjøres før neste utbygging i denne byen.</p></section>`;}
function ownerHistory(card){const history=ownerArray(card.history);if(!history.length)return '';return `<details class="owner-history"><summary>Det som er avtalt i ${ownerText(ownerCityName(card.city))} · ${history.length}</summary><div>${history.slice().reverse().map(h=>`<article><span class="section-kicker">${Number.isFinite(h.week)?'UKE '+(h.week+1):Number.isFinite(h.day)?'DAG '+h.day:'AVTALE'}</span><h3>${ownerText(h.title||h.label||h.text||({invest:'Utbygging '+h.level+' / '+ownerPathName(h.path),share:'Den neste avtalen ble delt',buyout:'En bindende våpenhvile',hold:'Laget holdt avtalen'})[h.kind]||'Et valg ved bordet')}</h3>${h.text&&h.text!==h.title?`<p>${ownerText(h.text)}</p>`:''}${Number.isFinite(h.cost)?`<small>${ownerMoney(h.cost)}${h.automatic?' · fulgt opp av lederne':''}</small>`:''}</article>`).join('')}</div></details>`;}
function ownerDossier(card,info){const pending=ownerArray(info.pending).find(p=>p.city===card.city),quotes=ownerArray(card.quotes).filter(q=>!card.path||q.path===card.path);return `${pending?ownerDecision(pending):''}<section class="owner-dossier"><div class="owner-file-heading"><div><span class="section-kicker">${ownerText(ownerCityName(card.city))} / ${ownerText(ownerPhase(card))}</span><h2>${ownerText(card.title)}</h2></div><span class="owner-file-no" aria-hidden="true">0${card.city+1}<small>EIERMAPPE</small></span></div><div class="owner-story"><div class="owner-contact-voice">${G.contactPortrait?.(card.contact)?`<span class="owner-contact-face">${G.contactPortrait(card.contact)}</span>`:''}<div><span class="section-kicker">${ownerText(card.contact)}</span><p>${ownerText(card.setting)}</p></div></div><div class="owner-opposition"><span class="section-kicker">PÅ ANDRE SIDEN AV BORDET</span><b>${ownerText(card.rival)}</b><p>${card.path?ownerText(ownerPathName(card.path))+' er avtalt. '+(card.path==='control'?'Du beholder styringen, og rivalene følger veksten tett.':'Lokale medeiere deler resultatet og innflytelsen.'):'Et oppkjøp forandrer hvem som får bestemme. Den første avtalen setter retningen for senere trinn.'}</p></div></div>${card.level>0?`<div class="owner-current"><span>Avtalt eierskap<b>${ownerText(ownerPathName(card.path))}</b></span><span>Netto før driftsstrategi<b>${ownerMoney((card.income||0)-(card.upkeep||0))} / uke</b></span><span>Lokalt rivalpress<b>${Math.round(card.pressure||0)} / 100</b></span><span>Motstand rundt avtalen<b>${card.tension>=7?'Sterk':card.tension>=3?'Økende':'Lav'}</b></span></div>`:''}${ownerProgress(card)}${card.level>=card.maxLevel&&!card.project?`<div class="owner-completed"><span aria-hidden="true">✓</span><div><h3>Avtalen står. Menneskene blir igjen.</h3><p>Alle ${card.maxLevel} trinn er fullført. Lederne følger driften, og nye spørsmål om eierskap kan fortsatt komme fra andre siden av bordet.</p></div></div>`:`<div class="owner-paths ${quotes.length===1?'owner-single-path':''}">${quotes.map(q=>ownerQuoteCard(q,card)).join('')}</div>`}</section>${ownerHistory(card)}`;}
function ownerMandateQuote(id){return typeof G.ownershipMandateQuote==='function'?G.ownershipMandateQuote(s,id):null;}
function ownerPolicy(info){const mandate=info.mandate||'manual';return `<details class="owner-policy"><summary>Vil du gi lederne en egen eierfullmakt?</summary><p>${ownerText(info.policyText||'Du tar eieravtalene selv til du uttrykkelig gir en fullmakt. En vanlig kapitalplan gir ikke i seg selv lov til å kjøpe selskaper.')}</p><div class="owner-policy-choices">${[['manual','Jeg tar eieravtalene selv'],['partners','La Nora finne lokale medeiere'],['control','La lederne kjøpe hele selskaper']].map(([id,label])=>{const q=ownerMandateQuote(id);return `<article><span class="section-kicker">${mandate===id?'DIN EIERFULLMAKT':'ET EGET MANDAT'}</span><h3>${ownerText(label)}</h3><p>${ownerText(q?.text||'Eieravtalene følges opp manuelt.')}</p>${q?.reason?`<p class="owner-quote-reason">${ownerText(q.reason)}</p>`:''}<button class="button ghost" data-owner-mandate="${id}" aria-pressed="${mandate===id}" ${s.ended||!q?.valid?'disabled':''}>${ownerText(mandate===id?'Valgt ✓':id==='manual'?'Velg selv':'Les og gi fullmakt →')}</button></article>`;}).join('')}</div><p class="small">Fullmakten bruker ledernes vanlige kapitalrunde. Den gir ingen ekstra kjøpsrunde. En eierform som allerede er avtalt for et selskap, beholdes.</p></details>`;}
function ownerConfirmMandate(id){const q=ownerMandateQuote(id);if(!q||!q.valid){toast(q?.reason||'Fullmakten kan ikke endres nå.');return;}if(id==='manual'){act(q.action||'ownershipMandate',q.arg??id);return;}modal(`<section class="owner-confirm"><span class="section-kicker">NORA / EN STÅENDE EIERFULLMAKT</span><h2>${ownerText(q.label||q.name||'La lederne følge opp eierskapet?')}</h2><p>${ownerText(q.text)}</p><p>Lederne kan binde kapital i selskaper og velge svar på mottilbud innenfor fullmakten. Les vilkårene over før du gir dem dette ansvaret.</p><div class="owner-confirm-actions"><button class="button brass" id="ownerMandateConfirm">Gi denne eierfullmakten</button><button class="button ghost" id="ownerMandateCancel">Tenk videre</button></div></section>`);$('#ownerMandateCancel').onclick=()=>$('#dialog').close();$('#ownerMandateConfirm').onclick=()=>{const latest=ownerMandateQuote(id);if(!latest?.valid||latest.text!==q.text||JSON.stringify(latest.arg)!==JSON.stringify(q.arg)){toast(latest?.reason||'Vilkårene er endret. Les fullmakten på nytt.');$('#dialog').close();render();return;}$('#dialog').close();act(latest.action||'ownershipMandate',latest.arg??id);};}
function ownershipView(){const info=ownerInfo(),card=ownerPick(info),total=ownerArray(info.projects).filter(p=>p.level>0).length;if(!card)return `<section class="owner-board"><div class="page-title"><div><span class="section-kicker">EIERBORDET</span><h1>DET NESTE BORDET<br>BLIR DEKKET.</h1><p>Avtalene er ikke tilgjengelige i denne versjonen av lagringen ennå.</p></div></div></section>`;return `<section class="owner-board"><header class="owner-page-header"><div><span class="section-kicker">EIERBORDET / FEM BYER. ULIKE VILKÅR.</span><h1>ET NAVN PÅ DØRÅ.<br>NOEN ANDRE VED BORDET.</h1><p>Kapital kan kjøpe en virksomhet. Hvem du deler den med, bestemmer hva den blir.</p></div><div class="owner-cover-stamp"><span>VÅGEN</span><b>2026<br>2036</b><small>AVTALER SOM SETTER SPOR</small></div></header><div class="owner-overview"><span>Byer med eierskap<b>${total} / ${ownerArray(info.projects).length}</b></span><span>Produktiv kapital bundet<b>${ownerMoney(info.invested)}</b></span><span>Netto før driftsstrategi<b>${ownerMoney((info.income||0)-(info.upkeep||0))} / uke</b></span>${Number.isFinite(info.reserve)?`<span>Holdes av til drift og gjeld<b>${ownerMoney(info.reserve)}</b></span>`:''}</div>${s.rankLevel<5&&!s.ended?'<aside class="owner-introduction"><b>Nora har lagt fem mapper til side.</b><p>Disse avtalene åpner som Gudfar. Først bygger du et nettverk som kan bære dem. Du kan lese vilkårene nå.</p></aside>':''}${s.ended?'<aside class="owner-introduction"><b>Tiåret er over.</b><p>Her står avtalene og valgene du etterlot deg. Ingen nye kjøp eller svar kan gjennomføres.</p></aside>':''}${ownerArray(info.pending).length&&!ownerArray(info.pending).some(p=>p.city===card.city)?`<button class="owner-waiting" data-owner-city="${info.pending[0].city}"><span>Et svar venter i ${ownerText(ownerCityName(info.pending[0].city))}</span><b>Les tilbudet →</b></button>`:''}${ownerCityTabs(info,card)}${ownerDossier(card,info)}${ownerPolicy(info)}<p class="owner-footnote">Et trinn gir inntekt når den avtalte oppbyggingen er fullført. Pengene trekkes ved signering. Inntektsanslagene er før driftsstrategi. Tilbakebetaling er et forsiktig anslag, og oppkjøp er ingen garanti for ro.</p></section>`;}
function ownerInvite(info,small=false){const pending=ownerArray(info.pending)[0],active=ownerArray(info.projects).find(p=>p.project),candidate=ownerPick(info),title=pending?.title||active?.title||'Hvem får en stol ved ditt bord?',text=pending?.text||active?.setting||'Nora har funnet virksomheter i fem byer. Velg hvem som skal eie veksten, og hvem som må leve med den.';return `<section class="owner-invite ${small?'owner-invite-small':''}"><div><span class="section-kicker">${pending?'ET SVAR VENTER':'NORA / EIERBORDET'}</span><h2>${ownerText(title)}</h2><p>${ownerText(text)}</p></div><button class="button brass" data-owner-open="${pending?.city??active?.city??candidate?.city??0}">${pending?'Les tilbudet':'Åpne eierbordet'} →</button></section>`;}
function ownerFindResponse(arg){const d=ownerArray(ownerInfo().pending).find(p=>p.city===arg.city&&p.revision===arg.revision);return d?.choices.find(q=>q.id===arg.choice)||null;}
function ownerQuoteFor(action,arg){return action==='ownershipInvest'&&typeof G.ownershipQuote==='function'?G.ownershipQuote(s,arg):action==='ownershipRespond'?ownerFindResponse(arg):null;}
function ownerConfirm(action,arg){const q=ownerQuoteFor(action,arg);if(!q||!q.valid||s.ended){toast(q?.reason||'Tilbudet er ikke lenger tilgjengelig.');return;}const title=q.title||q.label||'Et svar ved eierbordet',cost=q.cost||0;modal(`<section class="owner-confirm"><span class="section-kicker">${ownerText(ownerCityName(arg.city))} / LES FØR DU SIGNERER</span><h2>${ownerText(title)}</h2><p>${ownerText(q.text)}</p>${ownerEffects(q.effects)}<div class="owner-confirm-cash"><span>Trekkes fra kassa nå<b>−${ownerMoney(cost)}</b></span><span>Kasse etter signering<b>${ownerMoney(s.cash-cost)}</b></span></div>${Number.isFinite(q.reserve)?`<p>Beskyttet drifts- og gjeldsreserve: ${ownerMoney(q.reserve)}.</p>`:''}${action==='ownershipInvest'?`<p>${ownerText(q.deliveryRequirement||'Oppbyggingen følges opp gjennom faktiske driftsuker.')} Først etter fullføring gir dette trinnet anslagsvis ${ownerMoney(q.weeklyNet)} ekstra netto per uke før driftsstrategi og sesongvariasjon.</p>`:''}<div class="owner-confirm-actions"><button class="button brass" id="ownerConfirmAction">${action==='ownershipInvest'?'Signer avtalen':'Gi dette svaret'}</button><button class="button ghost" id="ownerKeepThinking">Tenk videre</button></div></section>`);$('#ownerKeepThinking').onclick=()=>$('#dialog').close();$('#ownerConfirmAction').onclick=()=>{const latest=ownerQuoteFor(action,arg);if(!latest||!latest.valid||latest.cost!==q.cost||JSON.stringify(latest.arg)!==JSON.stringify(q.arg)){toast(latest?.reason||'Tilbudet er endret. Les de nye vilkårene før du signerer.');$('#dialog').close();render();return;}$('#dialog').close();act(action,latest.arg);};}
if(!nav.some(n=>n[0]==='ownership'))nav.splice(Math.max(1,nav.findIndex(n=>n[0]==='scaling')+1),0,['ownership','00','Eierbordet']);nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const ownershipPriorRender=render;
render=function(){const current=view;if(current==='ownership')view='scaling';ownershipPriorRender();view=current;if(current==='ownership'){$('#screen').innerHTML=ownershipView();$('#nav').querySelectorAll('[data-view]').forEach(n=>{const active=n.dataset.view==='ownership';n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});}const tab=$('#nav [data-view="ownership"]');if(tab)tab.hidden=!(current==='ownership'||s.rankLevel>=5||exUI.all);if((current==='home'||current==='scaling')&&s.rankLevel>=5&&!s.ended){const target=current==='home'?$('.ex-next'):$('#screen>.page-title');if(target)target.insertAdjacentHTML('afterend',ownerInvite(ownerInfo(),current==='scaling'));}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-owner-city')){ownershipUI.city=+b.dataset.ownerCity;render();}if(b.hasAttribute('data-owner-open')){ownershipUI.city=+b.dataset.ownerOpen;view='ownership';render();window.scrollTo({top:0,behavior:'auto'});}if(b.hasAttribute('data-owner-invest'))ownerConfirm('ownershipInvest',{city:+b.dataset.ownerInvest,path:b.dataset.ownerPath,level:+b.dataset.ownerLevel});if(b.hasAttribute('data-owner-respond')){const arg={city:+b.dataset.ownerRespond,choice:b.dataset.ownerChoice,revision:+b.dataset.ownerRevision},q=ownerFindResponse(arg);if(q?.valid){if(q.cost)ownerConfirm('ownershipRespond',arg);else act('ownershipRespond',q.arg);}else toast(q?.reason||'Tilbudet er ikke lenger tilgjengelig.');}if(b.hasAttribute('data-owner-mandate'))ownerConfirmMandate(b.dataset.ownerMandate);});
render();
